using System.IO;using System.Text.Json;using System.Windows;using System.Windows.Media;using System.Windows.Media.Imaging;using RAWSelectionAssistant.Core.Services.Projects;using RAWSelectionAssistant.ViewModels;using RAWSelectionAssistant.Views;using RAWSelectionAssistant.Services;using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public sealed class LightTableWorkflowTests
{
 static string Root()=>Environment.GetEnvironmentVariable("KITAO_LIGHTTABLE_ROOT")??throw new InvalidOperationException("Explicit isolated root required");
 static string Image(string root,string name,int shift=0){Directory.CreateDirectory(root);var a=new byte[240*160*3];for(int y=0;y<160;y++)for(int x=0;x<240;x++){int i=(y*240+x)*3;a[i]=(byte)((x+shift)%251);a[i+1]=(byte)(y+20);a[i+2]=60;}var b=BitmapSource.Create(240,160,96,96,PixelFormats.Rgb24,null,a,720);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));var path=Path.Combine(root,name);using var f=File.Create(path);e.Save(f);return path;}
 static void Layout(FrameworkElement x){x.Measure(new Size(1366,768));x.Arrange(new Rect(0,0,1366,768));x.UpdateLayout();}
 static string Hash(BitmapSource b){var f=new FormatConvertedBitmap(b,PixelFormats.Bgra32,null,0);var a=new byte[f.PixelWidth*f.PixelHeight*4];f.CopyPixels(a,f.PixelWidth*4,0);return Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(a));}
 [TestMethod]public Task PinArrangeFilmCancelAndSaveActualProject()=>RunSta(async()=>
 {
  EnsureTestApplication();var root=Root();using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());await vm.LoadTargetAsync(Image(root,"a.png"));await vm.CreateR53VariantAsync(true);var first=vm.ActiveTarget!;first.IsSelected=true;await vm.LoadTargetAsync(Image(root,"b.png",40));await vm.CreateR53VariantAsync(true);vm.ActiveTarget!.IsSelected=true;vm.PinSelectedViewingVariants();Assert.AreEqual(2,vm.ViewingTable.Items.Count);var pinned=vm.ViewingTable.Items[0];var frozen=JsonSerializer.Serialize(pinned.FrozenVariant);vm.SetViewingPlacement(pinned.TargetId,pinned.VariantId,145,82,1.2,90);Assert.AreEqual(frozen,JsonSerializer.Serialize(vm.ViewingTable.Items[0].FrozenVariant));await vm.PrepareViewingTableAsync();Assert.AreEqual(2,vm.ViewingFrames.Count,vm.ViewingStatus);Assert.IsTrue(vm.ViewingCacheBytes<=64L*1024*1024);var table=new StudioViewingTableView(vm);await table.RefreshAsync();Layout(table);var image=new RenderTargetBitmap(1366,768,96,96,PixelFormats.Pbgra32);image.Render(table);var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(image));using(var f=File.Create(Path.Combine(root,"lighttable-OFFSCREEN.png")))enc.Save(f);
  var count=first.EditVersions.Count;using(var cancel=new CancellationTokenSource()){cancel.Cancel();try{await vm.GenerateViewingFilmAsync(pinned,token:cancel.Token);}catch(OperationCanceledException){}Assert.AreEqual(count,first.EditVersions.Count);}
  bool unavailable=false;try{await vm.GenerateViewingFilmAsync(pinned,"spektralab");}catch(NotSupportedException){unavailable=true;}Assert.IsTrue(unavailable);Assert.AreEqual(count,first.EditVersions.Count);
  using(var midCancel=new CancellationTokenSource()){System.ComponentModel.PropertyChangedEventHandler stop=(_,args)=>{if(args.PropertyName==nameof(vm.IsFilmTaskRunning)&&vm.IsFilmTaskRunning)midCancel.Cancel();};vm.PropertyChanged+=stop;var canceled=await vm.GenerateViewingFilmAsync(pinned,token:midCancel.Token);vm.PropertyChanged-=stop;Assert.IsNull(canceled);Assert.AreEqual(count,first.EditVersions.Count);}
  var result=await vm.GenerateViewingFilmAsync(pinned);Assert.IsNotNull(result);Assert.AreEqual(count+1,first.EditVersions.Count);var version=first.EditVersions.Single(v=>v.Id==result);Assert.IsNotNull(version.FilmBackend);Assert.IsTrue(version.Stack!.Nodes.Single(n=>n.Id==version.FilmBackend.RequestId).SystemLocked);Assert.AreEqual(pinned.VariantId,version.FilmBackend.SourceVariantId);var full=await vm.Editor.ProcessForExportAsync(first.Path,version.Look,version.Film,CancellationToken.None,version.Stack);Assert.AreEqual(240,full.PixelWidth);Assert.AreEqual(160,full.PixelHeight);Assert.AreEqual(32,full.Format.BitsPerPixel);Assert.AreEqual(8,version.FilmBackend.Output.Bits);Assert.AreEqual("sRGB",version.FilmBackend.Output.Space);Assert.ThrowsExactly<InvalidDataException>(()=>(version.FilmBackend with{Version=999}).Validate());Assert.ThrowsExactly<InvalidDataException>(()=>(version.FilmBackend with{Output=version.FilmBackend.Output with{Bits=16}}).Validate());Assert.AreEqual(frozen,JsonSerializer.Serialize(pinned.FrozenVariant));await vm.PrepareViewingTableAsync();Assert.AreEqual(3,vm.ViewingFrames.Count,vm.ViewingStatus);var resultFrame=vm.ViewingFrames.Single(f=>f.Item.VariantId==result);Assert.AreNotEqual(Hash(vm.ViewingFrames.Single(f=>f.Item.VariantId==pinned.VariantId).Image),Hash(resultFrame.Image));await vm.ReturnViewingToDarkroomAsync(resultFrame.Item);Assert.AreEqual(result,vm.ActiveTarget!.ActiveEditVersionId);Assert.AreEqual(first.Id,vm.ActiveTarget.Id);
  var project=Path.Combine(root,"table.ptstudio.json");await vm.SaveSessionAsync(project);Assert.IsNotNull(first.EditVersions.Single(v=>v.Id==result).FilmBackend);await File.WriteAllTextAsync(Path.Combine(root,"expected.json"),JsonSerializer.Serialize(new{pid=Environment.ProcessId,project,state=JsonSerializer.Serialize(vm.ViewingTable),result,hash=Hash(resultFrame.Image)}));table.Close();Assert.AreEqual(0,vm.ViewingCacheBytes);
 });
 [TestMethod]public Task IndependentViewingTableAndFilmReopen()=>RunSta(async()=>
 {
  EnsureTestApplication();var root=Root();using var d=JsonDocument.Parse(await File.ReadAllTextAsync(Path.Combine(root,"expected.json")));var x=d.RootElement;Assert.AreNotEqual(Environment.ProcessId,x.GetProperty("pid").GetInt32());using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());await vm.LoadSessionAsync(x.GetProperty("project").GetString()!);Assert.AreEqual(x.GetProperty("state").GetString(),JsonSerializer.Serialize(vm.ViewingTable));await vm.PrepareViewingTableAsync();Assert.AreEqual(3,vm.ViewingFrames.Count,vm.ViewingStatus);var result=x.GetProperty("result").GetGuid();Assert.AreEqual(x.GetProperty("hash").GetString(),Hash(vm.ViewingFrames.Single(f=>f.Item.VariantId==result).Image));Assert.IsNotNull(vm.Targets.SelectMany(t=>t.EditVersions).Single(v=>v.Id==result).FilmBackend);using var c=new CancellationTokenSource();c.Cancel();await vm.PrepareViewingTableAsync(c.Token);Assert.AreEqual(0,vm.ViewingFrames.Count);
 });
 [TestMethod]public Task MissingAndChangedSourcesNeverCommitOrReuseStalePixels()=>RunSta(async()=>
 {
  EnsureTestApplication();var root=Path.Combine(Root(),"failure");using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());var path=Image(root,"changed.png");await vm.LoadTargetAsync(path);await vm.CreateR53VariantAsync(true);vm.ActiveTarget!.IsSelected=true;vm.PinSelectedViewingVariants();var pinned=vm.ViewingTable.Items.Single();await vm.PrepareViewingTableAsync();Assert.AreEqual(1,vm.ViewingFrames.Count);var count=vm.ActiveTarget.EditVersions.Count;
  File.WriteAllBytes(path,[1,2,3,4]);await vm.PrepareViewingTableAsync();Assert.AreEqual(0,vm.ViewingFrames.Count);bool failed=false;try{await vm.GenerateViewingFilmAsync(pinned);}catch(IOException){failed=true;}Assert.IsTrue(failed);Assert.AreEqual(count,vm.ActiveTarget.EditVersions.Count);File.Delete(path);await vm.PrepareViewingTableAsync();Assert.AreEqual(0,vm.ViewingFrames.Count);Assert.AreEqual(pinned,vm.ViewingTable.Items.Single());Assert.AreEqual(0,vm.ViewingFrames.Count);
  using var high=new ReferenceColorWorkspaceViewModel(new Dialogs());var pixels=Enumerable.Repeat((ushort)22000,40*30*4).ToArray();for(int i=3;i<pixels.Length;i+=4)pixels[i]=ushort.MaxValue;var bitmap=BitmapSource.Create(40,30,96,96,PixelFormats.Rgba64,null,pixels,40*8);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));var highPath=Path.Combine(root,"high16.png");using(var file=File.Create(highPath))encoder.Save(file);await high.LoadTargetAsync(highPath);await high.CreateR53VariantAsync(true);high.ActiveTarget!.IsSelected=true;high.PinSelectedViewingVariants();var highCount=high.ActiveTarget.EditVersions.Count;bool rejected=false;try{await high.GenerateViewingFilmAsync(high.ViewingTable.Items.Single());}catch(NotSupportedException){rejected=true;}Assert.IsTrue(rejected);Assert.AreEqual(highCount,high.ActiveTarget.EditVersions.Count);
  var invalid=vm.ViewingTable with{Version=999};Assert.ThrowsExactly<InvalidDataException>(()=>invalid.Validate());Assert.ThrowsExactly<InvalidDataException>(()=>(pinned with{RecipeHash=new string('0',64)}).Validate());
 });
 [TestMethod]public Task ExistingTaskCenterTracksFilmBackendCompletion()=>RunSta(async()=>
 {
  EnsureTestApplication();var root=Path.Combine(Root(),"tracked");Directory.CreateDirectory(root);
  var db=new RAWSelectionAssistant.Core.Services.Database.PixelTartDatabase(Path.Combine(root,"task.sqlite"));await new RAWSelectionAssistant.Core.Services.Database.DatabaseMigrator(db,new RAWSelectionAssistant.Core.Services.Database.DatabaseBackupService(db,Path.Combine(root,"backups"))).MigrateAsync();
  var repository=new RAWSelectionAssistant.Core.Services.Tasks.SqliteTaskRepository(db);var bridge=new RAWSelectionAssistant.Core.Services.Tasks.TaskOperationBridge();var engine=new RAWSelectionAssistant.Core.Services.Tasks.TaskEngine(repository,new RAWSelectionAssistant.Core.Services.Tasks.ConservativeTaskScheduler(),[bridge],new RAWSelectionAssistant.Core.Services.AuditLogService(db),new RAWSelectionAssistant.Core.Services.NotificationCenter(db,TimeSpan.Zero));bridge.Attach(engine);
  using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(),filmTaskBridge:bridge);await vm.LoadTargetAsync(Image(root,"tracked.png"));await vm.CreateR53VariantAsync(true);vm.ActiveTarget!.IsSelected=true;vm.PinSelectedViewingVariants();var result=await vm.GenerateViewingFilmAsync(vm.ViewingTable.Items.Single());Assert.IsNotNull(result);var history=await engine.LoadHistoryAsync();Assert.AreEqual(1,history.Count);Assert.AreEqual(RAWSelectionAssistant.Core.Models.TaskLifecycleState.Completed,history[0].State);Assert.AreEqual(1,history[0].ResultSummary.Succeeded);Assert.AreEqual("胶片渲染 · 固定变体",history[0].Definition.DisplayName);
 });
 [TestMethod]public Task ReplacementAndCanceledViewingKeepPinnedIdentity()=>RunSta(async()=>
 {
  EnsureTestApplication();var root=Path.Combine(Root(),"switch");using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());await vm.LoadTargetAsync(Image(root,"first.png"));await vm.CreateR53VariantAsync(true);vm.ActiveTarget!.IsSelected=true;vm.PinSelectedViewingVariants();var first=vm.ViewingTable.Items.Single();var parameter=ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.BasicTone).Single(p=>p.Key=="exposure");vm.Editor.AddAdjustmentNodeCommand.Execute("BasicTone");vm.Editor.SetToolParameter(parameter,.5);var end=DateTime.UtcNow.AddSeconds(15);while(!vm.Editor.IsSettled&&DateTime.UtcNow<end)await Task.Delay(10);await vm.PrepareViewingTableAsync();Assert.AreEqual(first,vm.ViewingTable.Items.Single());bool rejected=false;try{await vm.ReturnViewingToDarkroomAsync(first);}catch(IOException){rejected=true;}Assert.IsTrue(rejected);vm.PinSelectedViewingVariants(true);Assert.AreNotEqual(first.RecipeHash,vm.ViewingTable.Items.Single().RecipeHash);using(var c=new CancellationTokenSource()){var pending=vm.PrepareViewingTableAsync(c.Token);c.Cancel();await pending;Assert.AreEqual(0,vm.ViewingFrames.Count);}await vm.PrepareViewingTableAsync();Assert.AreEqual(1,vm.ViewingFrames.Count);vm.ReleaseViewing();Assert.AreEqual(0,vm.ViewingCacheBytes);
 });
 [TestMethod]public Task AuthorizedTenAndHundredNaturalPhotoViewingMeasurements()=>RunSta(async()=>
 {
  var manifest=Environment.GetEnvironmentVariable("KITAO_LIGHTTABLE_NATURAL_MANIFEST");if(manifest is null){Assert.Inconclusive("Explicit existing authorized photo manifest required");return;}EnsureTestApplication();var root=Path.Combine(Root(),"natural");Directory.CreateDirectory(root);var paths=JsonSerializer.Deserialize<string[]>(File.ReadAllText(manifest))!;Assert.AreEqual(100,paths.Length);var rows=new List<object>();
  foreach(var count in new[]{10,100}){
   using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());var watch=System.Diagnostics.Stopwatch.StartNew();long peak=0;var sources=new List<object>();
   foreach(var path in paths.Take(count)){
    using var stream=File.OpenRead(path);var hash=Convert.ToHexString(await System.Security.Cryptography.SHA256.HashDataAsync(stream));var target=new ReferenceTargetItem(path){SourceHash=hash,IsSelected=true};var version=new StudioEditVersion(Guid.NewGuid(),"授权自然照片",DateTimeOffset.UnixEpoch,null,null,hash,null,null,null,ColorStudioMatchEngine.Stable,MatchV4ExecutionMode.Auto){IsOriginal=true,IsMain=true};target.ActiveEditVersionId=version.Id;target.EditVersions.Add(version);vm.Targets.Add(target);sources.Add(new{targetId=target.Id,path,hash});
   }
   vm.PinSelectedViewingVariants();Assert.AreEqual(count,vm.ViewingTable.Items.Count);var preparation=watch.Elapsed.TotalMilliseconds;using var cts=new CancellationTokenSource();var sampling=Task.Run(async()=>{while(!cts.IsCancellationRequested){using var process=System.Diagnostics.Process.GetCurrentProcess();peak=Math.Max(peak,process.WorkingSet64);try{await Task.Delay(15,cts.Token);}catch(OperationCanceledException){}}});watch.Restart();await vm.PrepareViewingTableAsync();var loadMs=watch.Elapsed.TotalMilliseconds;cts.Cancel();await sampling;
   var loaded=vm.ViewingFrames.Count;var table=new StudioViewingTableView(vm);watch.Restart();await table.RefreshAsync();Layout(table);var controlMs=watch.Elapsed.TotalMilliseconds;watch.Restart();foreach(var item in vm.ViewingTable.Items.Take(10))vm.SetViewingPlacement(item.TargetId,item.VariantId,item.X+3,item.Y+3,item.Scale,15);var placementMs=watch.Elapsed.TotalMilliseconds;var cacheBytes=vm.ViewingCacheBytes;var frameBytes=vm.ViewingFrames.Sum(f=>(long)f.Image.PixelWidth*f.Image.PixelHeight*4);Assert.IsTrue(cacheBytes<=64L*1024*1024);Assert.IsTrue(frameBytes<=40L*1024*1024);
   rows.Add(new{requested=count,loaded,preparationMs=preparation,loadMs,controlLayoutMs=controlMs,tenPlacementUpdatesMs=placementMs,cacheBytes,frameBytes,peakSampledWorkingSet=peak,scope="authorized RAW/Real photos; decode and actual WPF layout; not native mouse latency",status=vm.ViewingStatus,failures=vm.ViewingFailures,sources});table.Close();Assert.AreEqual(0,vm.ViewingCacheBytes);Assert.AreEqual(0,vm.ViewingFrames.Count);await File.WriteAllTextAsync(Path.Combine(root,"MEASUREMENTS.json"),JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));
  }
 });
